package dk.jamesbabz.madkursus.inbound.rest.mealplan;
import java.time.ZoneOffset; import dk.jamesbabz.madkursus.inbound.rest.dto.*; import dk.jamesbabz.madkursus.inbound.rest.recipe.RecipeRestMapper; import dk.jamesbabz.madkursus.service.models.MealPlan; import lombok.RequiredArgsConstructor; import org.springframework.stereotype.Component;
@Component @RequiredArgsConstructor public class MealPlanRestMapper { private final RecipeRestMapper recipes; public MealPlanDTO toDto(MealPlan p){return new MealPlanDTO(p.id(),p.name(),p.createdAt().atOffset(ZoneOffset.UTC),p.updatedAt().atOffset(ZoneOffset.UTC),p.recipes().stream().map(r->new PlannedRecipeDTO(r.id(),recipes.toDto(r.recipe()),r.portions(),r.sortOrder(),PlannedRecipeStatusDTO.valueOf(r.status().name()))).toList(),p.completed());} }
